        providerId: 'password',
        input: { email: 'ada@example.com', password: 'wrong' },
      })).rejects.toMatchObject({ code: 'AUTH/INVALID_CREDENTIALS' })
    }

    await expect(auth.flows.signIn({
      providerId: 'password',
      input: { email: 'ada@example.com', password: 'wrong' },
    })).rejects.toMatchObject({ code: 'AUTH/RATE_LIMITED' })
  })
})
