function SignInForm() {
  const signIn = authUseSignIn()
  const [email, setEmail] = createSignal('')
  const [password, setPassword] = createSignal('')

  return (
    <form
      onSubmit={async (e) => {
        e.preventDefault()
        await signIn.mutate({
          providerId: 'password',
          input: { email: email(), password: password() },
        })
      }}
